js.text:

function grid$s41Hold(f){
  this.constructor(f);
}
grid$s41Hold.prototype = new DirEvent();
grid$s41Hold.prototype.afterInit = function(renderType){
  var p = this._dir;
  if (p.options._status == 4) p.find(".toolbar-approve").attr('title', p.msg('approve'))
  else if (p.options._status == 5) p.find(".toolbar-approve").attr('title', p.msg('undo'))
  else p.find(".toolbar-approve").attr('title', p.msg('open'));
  p.find(".toolbar-cancel").css("display", (p.options._status == 4)?"":"none")
}
grid$s41Hold.prototype.beforeButtonGridClick = function (id, gindex) {
  var msg, p = this._dir, g = p.grid(gindex), dt = g.data, fees = p.selectedItems(), xstatus = p.options._status;
  switch (id) {
    case 'approve':
      msg = (xstatus == 4)? p.msg('msg1'): (xstatus == 9)? p.msg('msg3'):p.msg('msg2');
      if (fees.count() > 0)
        $.question(msg, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v){
            p.request('Approve', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        });
      return false;
      break;
    case 'cancel':
      if (fees.count() > 0)
        p.showFilter('messageInput', null, {title: p.msg('inputTitle'), label: p.msg('reason'), allowBlank: false, msgFunction: function (q, v, ctext) {
          q._close();
          if (v){
            p.request('Close', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus], ['ly_do_huy', 'C', ctext]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        }});
      return false;
      break;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
